import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,a as s,b as r,c as i,d as o}from"./chunks/M-STA5.Cj8YAhfJ.js";import{_ as n,o as c,c as l,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Statistics","description":"","frontmatter":{},"headers":[],"relativePath":"use/statistics.md","filePath":"use/statistics.md"}'),m={name:"use/statistics.md"};function p(h,e,u,b,g,f){return c(),l("div",null,[...e[0]||(e[0]=[d('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> Statistics</p></div><p>Statistics view offers 3 basic statistics displays you can configure for different periods of time.</p><ol><li>First select the period of time you want to calculate statistics on. ToDay, YesTerDay, last 7, 30 or 90 days.</li><li>You can display the graph full screen (touch it again to exit full screen mode).</li><li>You can share the screen as a screenshot.</li></ol><img src="'+a+'" style="zoom:75%;"><br><p>First screen shows your numbers.</p><img src="'+s+'" style="zoom:75%;"><p>Percentage in range is calculated using low and high values range defined in Menu - Glucose Units.<br> Absolute numbers count the number of measurements in range, above and below.<br> Median BG is the central value of your data: same number of measurements above and below.<br> Mean BG is the mathematical average of all measurements.<br> Estimated HbA1c is only a mathematical calculation based on the average BG, and converted to mmol/mol or percent.<br> StdDev or standard deviation is the mathematical result of the calculation. It shows the dispersion of your BG.<br> Relative SD (CV) is the StdDev divided by mean and also shows the dispersion of your measurements.<br> GVI and PGS were parameters introduced by Dexcom, see <a href="https://web.archive.org/web/20160523152519/http://www.healthline.com/diabetesmine/a-new-view-of-glycemic-variability-how-long-is-your-line" target="_blank" rel="noreferrer">here</a>.</p><p>Look <a href="https://diatribe.org/understanding-average-glucose-standard-deviation-cv-and-blood-sugar-variability" target="_blank" rel="noreferrer">here</a> for explanations of these parameters, and remember they are based on measurements and depend on their quality. Bad measurements (inaccurate) will lead to bad statistics, whether it is because of the sensor accuracy or your calibrations.</p><p>You can choose which of these values are shown. Touch the menu (⋮) top right and select <code>Parameters</code>, then check or uncheck: Absolute #s, Median BG, Estimated A1C, Relative SD, GVI, PGS, Standard Deviation.</p><br><p>Swipe towards the left to see a graphical representation of your percentage in range.<br> Green is in range, yellow above and red below target.</p><img src="'+r+'" style="zoom:75%;"><br><p>Swipe again to see the percentile chart.</p><img src="'+i+'" style="zoom:75%;"><p>Rotate the screen to make it look better.</p><img src="'+o+'" style="zoom:50%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Last modified 6/7/2026</em></a></p>',20)])])}const S=n(m,[["render",p]]);export{v as __pageData,S as default};
